window.__votdWeek && window.__votdWeek({"week":"2029-11-05","reading":"Doctrine and Covenants 125–128","days":[{"d":"2029-11-05","ref":"D&C 125:2","b":"D&C","c":125,"v":2,"he":"אָמֵן כֹּה אָמַר יְהוָה אֲנִי אֹמֵר לָכֶם אִם הַקֹּרְאִים לְעַצְמָם בִּשְׁמִי וְהַמְבַקְשִׁים לִהְיוֹת קְדוֹשַׁי אִם יַעֲשׂוּ רְצוֹנִי וְיִשְׁמְרוּ מִצְוֹתַי עֲלֵיהֶם יִתְקַבְּצוּ אֶל־הַמְּקוֹמוֹת אֲשֶׁר אֲיַעֵד לָהֶם עַל־יְדֵי עַבְדִּי יוֹסֵף וְיִבְנוּ עָרִים לִשְׁמִי לְמַעַן יִהְיוּ נְכוֹנִים לַאֲשֶׁר צָפוּן לָעֵת הַבָּאָה׃","en":"Verily, thus saith the Lord, I say unto you, if those who call themselves by my name and are essaying to be my saints, if they will do my will and keep my commandments concerning them, let them gather themselves together unto the places which I shall appoint unto them by my servant Joseph, and build up cities unto my name, that they may be prepared for that which is in store for a time to come."},{"d":"2029-11-06","ref":"D&C 125:3","b":"D&C","c":125,"v":3,"he":"יִבְנוּ עִיר לִשְׁמִי עַל הָאָרֶץ נֹכַח עִיר נָאווּ וְיִקָּרֵא עָלֶיהָ שֵׁם זָרַהֶמְלָה׃","en":"Let them build up a city unto my name upon the land opposite the city of Nauvoo, and let the name of Zarahemla be named upon it."},{"d":"2029-11-07","ref":"D&C 126:1","b":"D&C","c":126,"v":1,"he":"אָחִי הַיָּקָר וְהָאָהוּב בְּרִיגָּם יַנְג אָמֵן כֹּה אָמַר יְהוָה אֵלֶיךָ עַבְדִּי בְּרִיגָּם לֹא נִדְרָשׁ עוֹד מִיָּדְךָ לַעֲזֹב אֶת־מִשְׁפַּחְתְּךָ כִּתְמוֹל שִׁלְשֹׁם כִּי קָרְבָּנְךָ רָצוּי לִי׃","en":"Dear and well-beloved brother, Brigham Young, verily thus saith the Lord unto you: My servant Brigham, it is no more required at your hand to leave your family as in times past, for your offering is acceptable to me."},{"d":"2029-11-08","ref":"D&C 126:3","b":"D&C","c":126,"v":3,"he":"לָכֵן אֲנִי מְצַוְּךָ לִשְׁלֹחַ דְּבָרִי לְמֶרְחָק וְלִשְׁמֹר מְאֹד אֶת־מִשְׁפַּחְתְּךָ מֵעַתָּה וָהָלְאָה וּלְעוֹלָם אָמֵן׃","en":"I therefore command you to send my word abroad, and take especial care of your family from this time, henceforth and forever. Amen."},{"d":"2029-11-09","ref":"D&C 127:3","b":"D&C","c":127,"v":3,"he":"לָכֵן יִשְׂמְחוּ כׇּל הַקְּדוֹשִׁים וְיָגִילוּ מְאֹד כִּי אֱלֹהֵי יִשְׂרָאֵל אֱלֹהֵיהֶם וְהוּא יָשִׁיב גְּמוּל צֶדֶק עַל רֹאשׁ כׇּל לֹחֲצֵיהֶם׃","en":"Let all the saints rejoice, therefore, and be exceedingly glad; for Israel's God is their God, and he will mete out a just recompense of reward upon the heads of all their oppressors."},{"d":"2029-11-10","ref":"D&C 127:9","b":"D&C","c":127,"v":9,"he":"וְיִהְיוּ כׇּל הָרִשֻּׁמוֹת מְסֻדָּרִים וְיִשָּׁמְרוּ בְּגִנְזֵי הֵיכָלִי הַקָּדוֹשׁ לְזִכָּרוֹן מִדּוֹר לָדוֹר נְאֻם יְהוָה צְבָאוֹת׃","en":"And again, let all the records be had in order, that they may be put in the archives of my holy temple, to be held in remembrance from generation to generation, saith the Lord of Hosts."},{"d":"2029-11-11","ref":"D&C 128:2","b":"D&C","c":128,"v":2,"he":"כָּתַבְתִּי לָכֶם מְעַט דִּבְרֵי חָזוֹן עַל־דְּבַר הַסּוֹפֵר וְעוֹד נִגְלוּ לִי דְּבָרִים אֲחָדִים עַל־הָעִנְיָן הַזֶּה אֲשֶׁר אֲנִי מֵעִיד עֲלֵיהֶם עַתָּה וְהוּא כִּי נֶאֱמַר בְּאִגַּרְתִּי הָרִאשׁוֹנָה כִּי יִהְיֶה סוֹפֵר אֲשֶׁר יִהְיֶה עֵד רֹאֶה בְּעֵינָיו וְשֹׁמֵעַ בְּאׇזְנָיו לְמַעַן יִכְתֹּב עֵדוּת אֱמֶת לִפְנֵי יְהוָה׃","en":"I wrote a few words of revelation to you concerning a recorder. I have had a few additional views in relation to this matter, which I now certify. That is, it was declared in my former letter that there should be a recorder, who should be eye-witness, and also to hear with his ears, that he might make a record of a truth before the Lord."}]});
